head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/

scwin.vScrenID = "ULDFIS00218.xml";
// 전역 변수 선언
scwin.vKisCd = ""; // 조회조건 기업코드
scwin.vAcntclsDt = ""; // 조회조건 결산일자
let acntclsDtArray = new Array();

/**
 *  화면이 최초 로드될때 실행되는 초기화 이벤트
 *  (초기 데이터 조회나 컴포넌트 설정) 
 */

// scwin.onpageload, scwin.onpageunload 함수
scwin.onpageload = function() {
    scwin.init();
};

/**
 *  현재 로딩된 페이지가 초기화되거나 종료될때(다른 화면으로 이동하거나 페이지를 닫기전) 발생하는 이벤트
 *  (주로 SPA(Single Page Application) 환경에서 전역 자원을 해제하거나 메모리 누수 방지)
 */
scwin.onpageunload = function() {
};

// 일반 함수
/**
 *  화면 초기화
 */
scwin.init = function() {

    // 결산일자 조회
    $p.parent().frame_head.getWindow().scwin.fn_SrchAcntclsDt();

};

/**
 *  데이터셋 초기화
 */
scwin.initDs = function() {
    dlt_shortLongTermDebtListRes.setData([]);
};

/**
 *  조회조건 유효성 체크
 */
scwin.chkValid = function() {

    //필수항목 체크
    scwin.vKisCd = $p.parent().frame_head.getWindow().scwin.fn_GetKisCd();
    scwin.vAcntclsDt = $p.parent().frame_head.getWindow().scwin.fn_GetAcntclsDt();

    if (scwin.vKisCd === "" || scwin.vAcntclsDt === "") {
        return false;
    }

    return true;

};

/**
 * 장단기차입금  조회
 */
scwin.search = async function() {

    //데이터셋 초기화
    scwin.initDs();

    // 조회조건 체크
    if (!scwin.chkValid()) {
        return;
    }

    dma_shortLongTermDebtInfoReq.set("kisCd", scwin.vKisCd);
    dma_shortLongTermDebtInfoReq.set("acntclsDtList", acntclsDtArray);

    const sbmOptions = {
        id : "sbm_shortLongTermDebt",
        action : "/api/listing/nice/company-status/short-long-term-debt",
        method : "get",
        ref : "dma_shortLongTermDebtInfoReq",
        target : "dlt_shortLongTermDebtListRes|append",
        gridview : "grd_lstrmDebtStat",
        isProcessMsg : false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    dlt_shortLongTermDebtListRes.setJSON(res.responseJSON.body);

};

/**
 * 그리드 헤더의 제목을 세팅
 */
scwin.setGrdHeaderNm = function(pArray) {

    acntclsDtArray = []; // 배열 초기화

    grd_lstrmDebtStat.setHeaderValue("h_AMT1", pArray[0].text);
    grd_lstrmDebtStat.setHeaderValue("h_AMT2", pArray[1].text);
    grd_lstrmDebtStat.setHeaderValue("h_AMT3", pArray[2].text);

    for (let i=0; i < pArray.length; i++) {
        acntclsDtArray.push(pArray[i].value);
    }

};

/**
 *  엑셀파일다운로드
 */
scwin.excelDownload = function() {

    if (dlt_shortLongTermDebtListRes.getRowCount() <= 0) {
        alert("조회된 데이터가 없습니다.");
        return;
    }

    const options = {
        fileName : "장단기차입금현황",
        sheetName : "장단기차입금현황"
    };

    const infoArray = {};

    grd_lstrmDebtStat.advancedExcelDownload(options, infoArray);

};
